            document.getElementById('date-updated').innerText = `TS: ${data.last_updated} | V3.0-FINAL`;
            // Update systemic fatigue score display
            document.getElementById('systemic-fatigue-score').innerText = data.systemic_muscle_fatigue || '--';

            // Set Load Distribution Date Range (still relevant)
            const allVolDates = Object.keys(data.daily_vol).filter(d => Object.values(data.daily_vol[d]).some(v => v > 0)).sort();
            if (allVolDates.length > 0) {
                const start = new Date(allVolDates[0] + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric'});
                const end = new Date(allVolDates[allVolDates.length - 1] + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric'});
                document.getElementById('volume-range').innerText = `(${start} - ${end})`;
            }

            // Populate Individual Muscle Fatigue List
            const individualFatigueList = document.getElementById('individual-fatigue-list');
            if (data.muscle_fatigue_parts) {
                for (const [part, score] of Object.entries(data.muscle_fatigue_parts)) {
                    let color = '#32d74b'; // Green (optimal default)
                    if (score > 120) color = '#ff453a'; // Red (overloaded significantly)
                    else if (score < 80 && score > 0) color = '#ff453a'; // Red (under-recovered/under-stimulated)
                    else if (score >= 80 && score <= 120) color = '#32d74b'; // Green (optimal)
                    else if (score > 120 && score <= 150) color = '#ffd60a'; // Yellow (slightly overloaded)
                    else if (score < 80 && score >= 50) color = '#ffd60a'; // Yellow (slightly under-recovered)

                    individualFatigueList.innerHTML += `
                        <div style="display: flex; justify-content: space-between; margin-bottom: 5px;">
                            <span style="color: #8e8e93;">${part}</span>
                            <span style="color: ${color}; font-weight: bold;">${score}%</span>
                        </div>
                    `;
                }
            }

            // Monthly Volume List
            const monthlyVolumeList = document.getElementById('monthly-volume-list');
            if (data.monthly_volume) {
                for (const [part, vol] of Object.entries(data.monthly_volume)) {
                    if (vol > 0) {
                        monthlyVolumeList.innerHTML += `
                            <div class="muscle-label">
                                <span>${part}</span>
                                <span><b>${vol.toLocaleString()}</b> lbs</span>
                            </div>
                        `;
                    }
                }
            }

            // Volume List & Body Color
            const volumeList = document.getElementById('volume-list');
            const maxVol = Math.max(...Object.values(data.volume));

            // Calculate last trained dates
            const lastTrained = {};
            Object.keys(data.volume).forEach(part => {
                // Find all dates where 'part' had volume
                const datesWithVolume = Object.keys(data.daily_vol)
                    .filter(d => data.daily_vol[d][part] > 0)
                    .sort();
                lastTrained[part] = datesWithVolume.length > 0 ? datesWithVolume[datesWithVolume.length - 1] : 'Never';
            });

            for (const [part, vol] of Object.entries(data.volume)) {
                if (part === 'Other' || vol == 0) continue; // Use == 0 to catch 0.0
                const percentage = (vol / maxVol) * 100;
                const date = lastTrained[part];
                const dateDisplay = date !== 'Never' ? new Date(date + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric'}) : 'N/A';

                volumeList.innerHTML += `
                    <div class="muscle-label">
                        <span>${part} <span style="font-size: 0.8em; color: #444; margin-left: 8px;">Last: ${dateDisplay}</span></span>
                        <span><b>${vol.toLocaleString()}</b> lbs</span>
                    </div>
                    <div class="volume-bar">
                        <div class="volume-fill" style="width: ${percentage}%"></div>
                    </div>
                `;

                // Update CSS variables for dynamic coloring (instead of direct style manipulation)
                const score = data.muscle_fatigue_parts[part] || 0;
                let color = '#32d74b';
                let applyGlow = false;

                if (score >= 80 && score <= 100) { color = '#32d74b'; }
                else if (score >= 50 && score < 80) { color = '#ffd60a'; applyGlow = true; }
                else if (score < 50 && score > 0) { color = '#ff453a'; applyGlow = true; }
                else if (score === 0) { color = '#32d74b'; applyGlow = false; }

                // Apply color and glow to corresponding CSS variables
                const root = document.documentElement;
                if (part === 'Arms') {
                    root.style.setProperty('--part-Arms-L-color', color);
                    root.style.setProperty('--part-Arms-R-color', color);
                    root.style.setProperty('--part-Arms-L-glow', applyGlow ? 'true' : 'false');
                    root.style.setProperty('--part-Arms-R-glow', applyGlow ? 'true' : 'false');
                } else if (part === 'Legs') {
                    root.style.setProperty('--part-Legs-L-color', color);
                    root.style.setProperty('--part-Legs-R-color', color);
                    root.style.setProperty('--part-Legs-L-glow', applyGlow ? 'true' : 'false');
                    root.style.setProperty('--part-Legs-R-glow', applyGlow ? 'true' : 'false');
                } else {
                    root.style.setProperty(`--part-${part}-color`, color);
                    root.style.setProperty(`--part-${part}-glow`, applyGlow ? 'true' : 'false');
                }
            }

            // Overload Chart
            const overloadCtx = document.getElementById('overloadChart').getContext('2d');

            const allOverloadDates = new Set();
            Object.values(data.overload).forEach(exData => {
                exData.forEach(d => allOverloadDates.add(d.date));
            });
            const sortedOverloadLabels = Array.from(allOverloadDates).sort();

            const exerciseNames = Object.keys(data.overload).slice(0, 5);
            const colors = ['#00ff88', '#00ccff', '#ff00ff', '#ffff00', '#ff8800'];

            const datasets = exerciseNames.map((ex, i) => {
                const chartData = sortedOverloadLabels.map(date => {
                    const found = data.overload[ex].find(d => d.date === date);
                    return found ? found.vol : null;
                });

                return {
                    label: ex,
                    data: chartData,
                    borderColor: colors[i],
                    backgroundColor: colors[i],
                    borderWidth: 2,
                    tension: 0.4,
                    pointRadius: 3,
                    pointHoverRadius: 6,
                    spanGaps: true
                };
            });

            new Chart(overloadCtx, {
                type: 'line',
                data: {
                    labels: sortedOverloadLabels,
                    datasets: datasets
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    interaction: {
                        intersect: false,
                        mode: 'index',
                    },
                    scales: {
                        y: {
                            display: true,
                            grid: { color: '#111', drawBorder: false },
                            ticks: {
                                color: '#555',
                                font: { size: 10 },
                                callback: (val) => (val >= 1000 ? (val / 1000).toFixed(1) + 'k' : val)
                            }
                        },
                        x: {
                            grid: { display: false },
                            ticks: { color: '#444', font: { size: 9 }, maxRotation: 45, minRotation: 45 }
                        }
                    },
                    plugins: {
                        legend: {
                            display: true,
                            position: 'top',
                            align: 'start',
                            labels: {
                                color: '#888',
                                boxWidth: 10,
                                font: { size: 10 },
                                padding: 10
                            }
                        },
                        tooltip: {
                            backgroundColor: '#0a0a0a',
                            titleColor: '#00ff88',
                            bodyColor: '#fff',
                            borderColor: '#333',
                            borderWidth: 1,
                            padding: 10,
                            displayColors: true,
                            callbacks: {
                                label: (context) => ` ${context.dataset.label}: ${context.parsed.y.toLocaleString()} lbs`
                            }
                        }
                    }
                }
            });

            // Nutrition Data
            if (data.nutrition && data.nutrition.length > 0) {
                const latest = data.nutrition[data.nutrition.length - 1];
                document.getElementById('nut-kcal').innerText = Math.round(latest.kcal);
                document.getElementById('nut-protein').innerText = Math.round(latest.protein) + 'g';
            }

            // Volume Trend (daily_vol for total volume trend bar chart)
            const volumeTrendCtx = document.getElementById('volumeTrendChart').getContext('2d');
            const sortedDatesForVolumeTrend = Object.keys(data.daily_vol).sort();
            new Chart(volumeTrendCtx, {
                type: 'bar',
                data: {
                    labels: sortedDatesForVolumeTrend.slice(-10),
                    datasets: [{
                        data: sortedDatesForVolumeTrend.slice(-10).map(d => Object.values(data.daily_vol[d]).reduce((a,b)=>a+b, 0)),
                        backgroundColor: '#111',
                        hoverBackgroundColor: '#00ff88',
                        borderRadius: 2
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: { y: { display: false } , x: { grid: { display: false } , ticks: { display: false } } } ,
                    plugins: { legend: { display: false } }
                }
            });
